INSERT INTO settings (key, value) VALUES 
  ('email_template_rejection_schriftfuehrer_subject', 'Bestellung abgelehnt - Protokoll: {{orderTitle}}'),
  ('email_template_rejection_schriftfuehrer_body', '<h2 style="color: #dc2626;">Bestellung abgelehnt</h2><p>Folgende Bestellung wurde abgelehnt und ist zur Protokollierung bestimmt.</p><div style="background: #fef2f2; padding: 16px; border-radius: 8px; margin: 16px 0; border-left: 4px solid #dc2626;"><p><strong>Bestellung:</strong> {{orderTitle}}</p><p><strong>Betrag:</strong> {{orderAmount}}</p><p><strong>Erstellt von:</strong> {{creatorName}}</p><p><strong>Abgelehnt von:</strong> {{approverName}} ({{approverRole}})</p><p><strong>Grund:</strong> {{rejectionReason}}</p></div><div style="background: #f3f4f6; padding: 16px; border-radius: 8px; margin: 16px 0;"><h3 style="margin-top: 0;">Abstimmungsergebnis</h3>{{votingResults}}</div><p>Diese Bestellung ist nun für weitere Bearbeitung gesperrt.</p>')
